'use strict';

/**
* Test whether an input value is an array of field instances.
*
* @module @stdlib/plot/vega/base/assert/is-field-array
*
* @example
* var Field = require( '@stdlib/plot/vega/field/ctor' );
* var isFieldArray = require( '@stdlib/plot/vega/base/assert/is-field-array' );
*
* var v = new Field({
*     'field': 'amount'
* });
* var bool = isFieldArray( [ v ] );
* // returns true
*
* bool = isFieldArray( {} );
* // returns false
*
* bool = isFieldArray( 'foo' );
* // returns false
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
